python
def chainTurntableBossReceipt(head, k):
    a=head
    out=[]
    previous=None
    node=a
    while node:
        next_node=node.next
        node.next=previous
        previous=node
        node=next_node
    node=previous
    while node:
        out.append(node.val)
        node=node.next
    return sum((i+1)*x for i,x in enumerate(out))


